34	 * An internal apr function to convert a double-null terminated set
35	 * of single-null terminated strings from wide Unicode to narrow utf-8
36	 * as a list of strings.  These are allocated from the MSVCRT's
37	 * _CRT_BLOCK to trick the system into trusting our store.
38	 */
39	static int warrsztoastr(const char * const * *retarr,
40	                        const wchar_t * arrsz)
41	{
42	    const apr_wchar_t *wch;
43	    apr_size_t totlen;
44	    apr_size_t newlen;
45	    apr_size_t wsize;
46	    char **env;
47	    char *pstrs;
48	    char *strs;
49	    int arg, args;
50	
51	    for (args = 1, wch = arrsz; wch[0] || wch[1]; ++wch)
52	        if (!*wch)
53	            ++args;
54	    wsize = 1 + wch - arrsz;
55	
56	    /* This is a safe max allocation, we will alloc each
57	     * string exactly after processing and return this
58	     * temporary buffer to the free store.
59	     * 3 utf-8 bytes hold any single utf-16 value (16 bits)
60	     * 4 utf-8 bytes will hold a 2 word utf-16 surrogate pair value (20 bits)
61	     */
62	    newlen = totlen = wsize * 3 + 1;
63	    pstrs = strs = apr_malloc_dbg(newlen * sizeof(char),
64	                                  __FILE__, __LINE__);
65	
66	    (void)apr_conv_utf16_to_utf8(arrsz, &wsize, strs, &newlen);
67	
68	    assert(newlen && !wsize);
69	
70	    *retarr = env = apr_malloc_dbg((args + 1) * sizeof(char*),
71	                                   __FILE__, __LINE__);
72	    for (arg = 0; arg < args; ++arg) {
73	        char* p = pstrs;
74	        int len = 0;
75	        while (*p++)
76	            ++len;
77	        len += 1;
78	
79	        *env = apr_malloc_dbg(len * sizeof(char),
80	                              __FILE__, __LINE__);
81	        memcpy(*env, pstrs, len * sizeof(char));
82	
83	        pstrs += len;
84	        ++env;
85	    }
86	
87	    *env = NULL;
88	    free(strs);
89	
90	    return args;
91	}
